func main() {
        app := pocketbase.New()

        // ---------------------------------------------------------------
        // Optional plugin flags:
        // ---------------------------------------------------------------

        var hooksDir string
        app.RootCmd.PersistentFlags().StringVar(
                &hooksDir,
                "hooksDir",
                "",
                "the directory with the JS app hooks",
        )

